import {chineseDate,shortDate} from './notice-model.js';
import {NOTICE_LAYOUT,noticeTextStyle,noticeTitleLayout,attachmentLayout,signoffLayout,noticeLayoutErrors} from './notice-layout.js';

// Normalize the controlled XML generated by the pinned docx 9.6.1 compiler.
// Its paragraph options omit character indents and adjustRightInd.
export function normalizeGongwenXml(xml){
 xml=xml.replace(/<w:(keepNext|keepLines|pageBreakBefore|suppressLineNumbers|widowControl)\b[^>]*\/>/g,'')
  .replace(/<w:(keepNext|keepLines|pageBreakBefore|suppressLineNumbers|widowControl)\b[^>]*>[\s\S]*?<\/w:\1>/g,'');
 const normalize=inner=>{
  inner=inner.replace(/<w:(adjustRightInd|snapToGrid)\b[^>]*\/>/g,'');
  const flags='<w:adjustRightInd w:val="0"/><w:snapToGrid w:val="0"/>';
  const at=inner.search(/<w:(spacing|ind|contextualSpacing|mirrorIndents|suppressOverlap|jc|textDirection|textAlignment|textboxTightWrap|outlineLvl|divId|cnfStyle|rPr|sectPr|pPrChange)\b/);
  inner=at<0?inner+flags:inner.slice(0,at)+flags+inner.slice(at);
  if(/w:pStyle w:val="Gongwen(?:Body|H[1-4])"/.test(inner)&&/w:firstLine="640"/.test(inner))inner=inner.replace(/<w:ind\b([^>]*?)\/>/,(_,attrs)=>`<w:ind${attrs.replace(/\s+w:firstLineChars="[^"]*"/,'')} w:firstLineChars="200"/>`);
  if(/w:pStyle w:val="Gongwen(?:Issuer|Date)"/.test(inner))inner=inner.replace(/<w:ind\b([^>]*?)\/>/,(_,attrs)=>{
   const right=Number(attrs.match(/w:right="(\d+)"/)?.[1]||0);return `<w:ind${attrs.replace(/\s+w:rightChars="[^"]*"/,'')} w:rightChars="${Math.round(right/320*100)}"/>`;
  });
  return '<w:pPr>'+inner+'</w:pPr>';
 };
 xml=xml.replace(/<w:pPr\s*\/>/g,()=>normalize('')).replace(/<w:pPr>([\s\S]*?)<\/w:pPr>/g,(_,inner)=>normalize(inner));
 return xml.replace(/<w:docGrid\b([^>]*?)\/>/g,(_,attrs)=>'<w:docGrid'+attrs.replace(/\s+w:charSpace="[^"]*"/,'')+' w:charSpace="0"/>');
}

export async function noticeDocx(doc){
  const date=chineseDate(doc.date),errors=noticeLayoutErrors(doc,date);
  if(!date)errors.push('请先填写有效的成文日期');if(!doc.issuer?.trim())errors.push('请先填写发文单位');if(errors.length)throw Error(errors[0]);
  const {Document,Packer,Paragraph,TextRun,Table,TableRow,TableCell,WidthType,AlignmentType,BorderStyle,LineRuleType,TableLayoutType,VerticalAlign,DocumentGridType}=await import('./vendor/docx.mjs');
  const L=NOTICE_LAYOUT,styles=['MainTitle','H1','H2','H3','H4','Body','Blank','AttachmentFirst','AttachmentItem','Issuer','Date','Addressee'].map(name=>({id:'Gongwen'+name,name:'Gongwen'+name}));
  const run=(text,font='仿宋_GB2312',size=32,breakBefore=0)=>new TextRun({text:noticeTextStyle(text),font:{name:font,eastAsia:font,cs:font},size,bold:false,color:'000000',...(breakBefore?{break:breakBefore}:{})});
  const para=(text,{style='GongwenBody',font='仿宋_GB2312',size=32,align=AlignmentType.JUSTIFIED,indent=true,spacing,...rest}={})=>new Paragraph({
    style,alignment:align,spacing:spacing||{line:590,lineRule:LineRuleType.AT_LEAST,before:0,after:0},
    indent:typeof indent==='object'?indent:indent?{firstLine:640}:undefined,children:[run(text,font,size)],...rest});
  const blank=()=>para('',{style:'GongwenBlank',indent:false});
  const body=text=>String(text??'').split(/\r?\n/).map(line=>line?para(line,{style:/^（\d+）/.test(line)?'GongwenH4':/^\d+\./.test(line)?'GongwenH3':'GongwenBody'}):blank());
  const heading=text=>para(text,{style:'GongwenH1',font:'黑体'}),subheading=text=>para(text,{style:'GongwenH2',font:'楷体_GB2312'});
  const border={style:BorderStyle.SINGLE,size:4,color:'000000'},widths=L.tableWidths;
  const cell=(value,index)=>new TableCell({width:{size:widths[index],type:WidthType.DXA},verticalAlign:VerticalAlign.CENTER,margins:{top:70,bottom:70,left:80,right:80},children:[para(value,{font:'宋体',size:24,indent:false,align:AlignmentType.CENTER,spacing:{line:360,lineRule:LineRuleType.AT_LEAST,before:0,after:0}})]});
  const rows=[['产品代码','产品名称','募集起始日','募集结束日'],...doc.rows.map(r=>[r.code,r.name,shortDate(r.start),shortDate(r.end)])];
  const table=new Table({width:{size:widths.reduce((a,b)=>a+b,0),type:WidthType.DXA},columnWidths:widths,layout:TableLayoutType.FIXED,borders:{top:border,bottom:border,left:border,right:border,insideHorizontal:border,insideVertical:border},
    rows:rows.map((values,index)=>new TableRow({tableHeader:index===0,cantSplit:true,children:values.map(cell)}))});
  const title=new Paragraph({style:'GongwenMainTitle',alignment:AlignmentType.CENTER,spacing:{line:590,lineRule:LineRuleType.AT_LEAST,before:0,after:360},children:noticeTitleLayout(doc.title).lines.map((line,index)=>run(line,'方正小标宋简体',44,index?1:0))});
  const b=doc.body,children=[title,para(`${doc.addressee}：`,{style:'GongwenAddressee',indent:false,align:AlignmentType.LEFT}),...body(b.intro),heading('一、产品发行安排及产品概况'),...body(b.schedule),table,
    heading('二、发行渠道'),...body(doc.channels),heading('三、发行区域'),...body(doc.region),heading('四、营销要点'),...body(b.marketing),
    subheading('（一）额度分配和维护'),...body(b.quota),subheading('（二）营销宣传'),...body(b.promotion),subheading('（三）其它要求'),...body(b.reporting),...body(b.printing),...body('特此通知。')];
  if(doc.attachments.length){children.push(blank());attachmentLayout(doc.attachments).forEach((a,index)=>children.push(para(a.prefix+a.name,{style:index?'GongwenAttachmentItem':'GongwenAttachmentFirst',align:AlignmentType.LEFT,indent:{left:Math.round(a.nameEm*320),hanging:Math.round(a.hangingEm*320)}})));}
  const sign=signoffLayout(doc.issuer,date);
  children.push(blank(),para(sign.issuer,{style:'GongwenIssuer',align:AlignmentType.RIGHT,indent:{right:sign.issuerRightTwips}}),para(sign.date,{style:'GongwenDate',align:AlignmentType.RIGHT,indent:{right:sign.dateRightTwips}}));
  const file=new Document({creator:'',title:doc.title,description:'',styles:{default:{document:{run:{font:{name:'仿宋_GB2312',eastAsia:'仿宋_GB2312'},size:32,color:'000000'}}},paragraphStyles:styles},sections:[{
    properties:{page:{size:L.page,margin:{...L.margin,gutter:0}},grid:{type:DocumentGridType.LINES,linePitch:Math.round((L.page.height-L.margin.top-L.margin.bottom)/22),charSpace:0}},children}]});
  const zip=Packer.compiler.compile(file,false);
  for(const [path,entry]of Object.entries(zip.files))if(!entry.dir&&path.endsWith('.xml')){
    let xml=normalizeGongwenXml(await entry.async('string'));
    if(path==='word/document.xml')xml=xml.replace(/<\/w:tblPr>/g,'<w:tblCaption w:val="GongwenDataTable"/></w:tblPr>');
    zip.file(path,xml);
  }
  return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',compression:'DEFLATE'});
}
